<?php require_once __DIR__ . '/../src/partials.php';$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare("SELECT m.*,p.code,p.name,u.full_name FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN users u ON u.id=m.user_id WHERE m.created_at::date BETWEEN ? AND ? ORDER BY m.created_at DESC LIMIT 500");$s->execute([$from,$to]);$rows=$s->fetchAll();page_start('รายการเคลื่อนไหวล่าสุด');?><div class="card"><form class="actions"><label>จาก</label><input type="date" name="from" value="<?=h($from)?>"><label>ถึง</label><input type="date" name="to" value="<?=h($to)?>"><button class="primary">กรอง</button></form></div><div class="table-wrap"><table><tr><th>วันที่</th><th>ประเภท</th><th>รหัส</th><th>สินค้า</th><th>จำนวน</th><th>อ้างอิง</th><th>ผู้ทำรายการ</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['created_at'])?></td><td><?=h($r['movement_type']==='IN'?'สินค้าเข้า':'สินค้าออก')?></td><td><?=h($r['code'])?></td><td><?=h($r['name'])?></td><td><?=h($r['quantity'])?></td><td><?=h($r['reference_no'])?></td><td><?=h($r['full_name'])?></td></tr><?php endforeach;?></table></div><?php page_end();
